{"path":"test/flutter_test_config.dart","content":"import 'dart:async';

import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';

/// Loads the app's bundled Roboto font before any test runs.
///
/// By default `flutter test` renders text with the "Ahem" font, which draws
/// solid boxes instead of glyphs. That makes golden images useless for
/// spotting real text-rendering regressions, so we load the real font the
/// app ships (see pubspec.yaml) for every widget and golden test.
Future<void> testExecutable(FutureOr<void> Function() testMain) async {
  setUpAll(() async {
    final regular = rootBundle.load('assets/fonts/Roboto-Regular.ttf');
    final bold = rootBundle.load('assets/fonts/Roboto-Bold.ttf');

    final fontLoader = FontLoader('Roboto')
      ..addFont(regular)
      ..addFont(bold);
    await fontLoader.load();
  });

  await testMain();
}
"}

{"path":"test/widget_test.dart","content":"// Smoke test: the app boots directly into the login screen and exposes
// its key building blocks (email field, password field, login button).

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:automated_app_sample_2/main.dart';
import 'package:automated_app_sample_2/screens/login_screen.dart';

void main() {
  testWidgets('App boots into the login screen', (WidgetTester tester) async {
    await tester.pumpWidget(const MyApp());

    expect(find.byType(LoginScreen), findsOneWidget);
    expect(find.byKey(const Key('loginEmailField')), findsOneWidget);
    expect(find.byKey(const Key('loginPasswordField')), findsOneWidget);
    expect(find.byKey(const Key('loginButton')), findsOneWidget);
  });
}
"}

{"path":"test/screens/login_screen_test.dart","content":"import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:automated_app_sample_2/screens/login_screen.dart';
import 'package:automated_app_sample_2/screens/register_screen.dart';
import 'package:automated_app_sample_2/widgets/app_logo.dart';

void main() {
  Widget buildSubject() {
    return const MaterialApp(home: LoginScreen());
  }

  group('LoginScreen layout', () {
    testWidgets('shows the company logo', (tester) async {
      await tester.pumpWidget(buildSubject());

      expect(find.byType(AppLogo), findsOneWidget);
    });

    testWidgets('shows an email field, a password field and a login button', (
      tester,
    ) async {
      await tester.pumpWidget(buildSubject());

      expect(find.byKey(const Key('loginEmailField')), findsOneWidget);
      expect(find.byKey(const Key('loginPasswordField')), findsOneWidget);
      expect(find.byKey(const Key('loginButton')), findsOneWidget);
    });

    testWidgets('shows a link to the register screen', (tester) async {
      await tester.pumpWidget(buildSubject());

      expect(find.byKey(const Key('registerLinkButton')), findsOneWidget);
      expect(find.text('Register'), findsOneWidget);
    });

    testWidgets('password field is obscured by default', (tester) async {
      await tester.pumpWidget(buildSubject());

      final passwordField = tester.widget<TextFormField>(
        find.byKey(const Key('loginPasswordField')),
      );
      expect(passwordField.obscureText, isTrue);
    });

    testWidgets('toggling visibility reveals the password text', (
      tester,
    ) async {
      await tester.pumpWidget(buildSubject());

      await tester.tap(find.byKey(const Key('togglePasswordVisibilityButton')));
      await tester.pump();

      final passwordField = tester.widget<TextFormField>(
        find.byKey(const Key('loginPasswordField')),
      );
      expect(passwordField.obscureText, isFalse);
    });
  });

  group('LoginScreen validation', () {
    testWidgets('shows errors when submitting empty fields', (tester) async {
      await tester.pumpWidget(buildSubject());

      await tester.tap(find.byKey(const Key('loginButton')));
      await tester.pump();

      expect(find.text('Please enter your email'), findsOneWidget);
      expect(find.text('Please enter your password'), findsOneWidget);
    });

    testWidgets('shows an error for an invalid email format', (tester) async {
      await tester.pumpWidget(buildSubject());

      await tester.enterText(
        find.byKey(const Key('loginEmailField')),
        'not-an-email',
      );
      await tester.tap(find.byKey(const Key('loginButton')));
      await tester.pump();

      expect(find.text('Please enter a valid email address'), findsOneWidget);
    });

    testWidgets('shows an error when the password is too short', (
      tester,
    ) async {
      await tester.pumpWidget(buildSubject());

      await tester.enterText(
        find.byKey(const Key('loginEmailField')),
        'user@example.com',
      );
      await tester.enterText(find.byKey(const Key('loginPasswordField')), '123');
      await tester.tap(find.byKey(const Key('loginButton')));
      await tester.pump();

      expect(
        find.text('Password must be at least 6 characters'),
        findsOneWidget,
      );
    });

    testWidgets('submits successfully with valid credentials', (
      tester,
    ) async {
      await tester.pumpWidget(buildSubject());

      await tester.enterText(
        find.byKey(const Key('loginEmailField')),
        'user@example.com',
      );
      await tester.enterText(
        find.byKey(const Key('loginPasswordField')),
        'password123',
      );
      await tester.tap(find.byKey(const Key('loginButton')));
      await tester.pump();

      expect(find.text('Login successful'), findsOneWidget);
      expect(find.text('Please enter your email'), findsNothing);
      expect(
        find.text('Password must be at least 6 characters'),
        findsNothing,
      );
    });
  });

  group('LoginScreen navigation', () {
    testWidgets('tapping Register navigates to the register screen', (
      tester,
    ) async {
      await tester.pumpWidget(buildSubject());

      await tester.tap(find.byKey(const Key('registerLinkButton')));
      await tester.pumpAndSettle();

      expect(find.byType(RegisterScreen), findsOneWidget);
    });
  });
}
"}

{"path":"test/golden/login_screen_golden_test.dart","content":"import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:automated_app_sample_2/main.dart';

void main() {
  // Real Roboto glyphs are loaded for all tests in
  // test/flutter_test_config.dart, so this golden captures actual readable
  // text instead of the default "Ahem" placeholder boxes.
  testWidgets('LoginScreen matches the golden image', (tester) async {
    tester.view.physicalSize = const Size(1080, 1920);
    tester.view.devicePixelRatio = 1.0;
    addTearDown(tester.view.reset);

    await tester.pumpWidget(const MyApp());
    await tester.pumpAndSettle();

    await expectLater(
      find.byType(MyApp),
      matchesGoldenFile('goldens/login_screen.png'),
    );
  });
}
"}

